'use strict';

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype;
}

function normalizePreferences(input) {
  if (input === undefined) return { theme: 'system', pageSize: 25, flags: {} };
  if (!isPlainObject(input)) throw new TypeError('Preferences must be a plain object');
  const allowed = new Set(['theme', 'pageSize', 'flags']);
  if (Reflect.ownKeys(input).some(key => typeof key !== 'string' || !allowed.has(key))) {
    throw new RangeError('Unknown preference');
  }

  const hasOwn = Object.prototype.hasOwnProperty;
  const theme = hasOwn.call(input, 'theme') ? input.theme : 'system';
  if (!['system', 'light', 'dark'].includes(theme)) throw new TypeError('Invalid theme');

  const pageSize = input.pageSize || 25;
  if (!Number.isSafeInteger(pageSize) || pageSize < 0 || pageSize > 100) {
    throw new TypeError('Invalid page size');
  }

  const sourceFlags = hasOwn.call(input, 'flags') ? input.flags : {};
  if (!isPlainObject(sourceFlags)) throw new TypeError('Flags must be a plain object');
  if (Reflect.ownKeys(sourceFlags).some(key => typeof key !== 'string')) {
    throw new TypeError('Invalid flag');
  }
  const flags = {};
  for (const key of Object.keys(sourceFlags)) {
    if (key.length === 0 || typeof sourceFlags[key] !== 'boolean') throw new TypeError('Invalid flag');
    flags[key] = sourceFlags[key];
  }
  return { theme, pageSize, flags };
}

module.exports = { normalizePreferences };

