'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['normalizePreferences']);
const { normalizePreferences } = api;

assert.deepStrictEqual(normalizePreferences(), { theme: 'system', pageSize: 25, flags: {} });
assert.deepStrictEqual(normalizePreferences({}), { theme: 'system', pageSize: 25, flags: {} });
assert.deepStrictEqual(normalizePreferences({ theme: 'dark' }), { theme: 'dark', pageSize: 25, flags: {} });
assert.deepStrictEqual(normalizePreferences({ pageSize: 0 }), { theme: 'system', pageSize: 0, flags: {} });
assert.deepStrictEqual(normalizePreferences({ pageSize: 100 }), { theme: 'system', pageSize: 100, flags: {} });

const flags = { beta: true, compact: false, experimental: true };
const input = { theme: 'light', pageSize: 50, flags };
const result = normalizePreferences(input);
assert.deepStrictEqual(result, input);
assert.notStrictEqual(result, input);
assert.notStrictEqual(result.flags, flags);
assert.deepStrictEqual(Object.keys(result.flags), ['beta', 'compact', 'experimental']);
result.flags.beta = false;
result.theme = 'dark';
assert.deepStrictEqual(input, { theme: 'light', pageSize: 50, flags: { beta: true, compact: false, experimental: true } });

const defaultsA = normalizePreferences();
const defaultsB = normalizePreferences();
assert.notStrictEqual(defaultsA, defaultsB);
assert.notStrictEqual(defaultsA.flags, defaultsB.flags);

for (const value of [null, [], 'dark', new Date(), Object.create(null)]) {
  assert.throws(() => normalizePreferences(value), TypeError);
}
for (const value of ['blue', '', null, undefined]) {
  assert.throws(() => normalizePreferences({ theme: value }), TypeError);
}
for (const value of [-1, 101, 1.5, NaN, Infinity, '25', Number.MAX_SAFE_INTEGER + 1]) {
  assert.throws(() => normalizePreferences({ pageSize: value }), TypeError);
}
for (const value of [null, [], Object.create(null), { yes: 1 }, { '': true }]) {
  assert.throws(() => normalizePreferences({ flags: value }), TypeError);
}
assert.throws(() => normalizePreferences({ theme: 'system', extra: true }), RangeError);

